if(!admin()&&$_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['login'])){
    verify_csrf();$email=strtolower(safe_text($_POST['email']??'',190));$password=is_string($_POST['password']??null)?$_POST['password']:'';$identifier=client_hash().'|'.$email;
    $allowed=!rate_limited('admin_login',$identifier,5,900)&&!rate_limited('admin_login_ip',client_hash(),20,900);$human=captcha_verify($_POST['captcha']??'');
    $stmt=$db->prepare('SELECT * FROM admin_users WHERE email=?');$stmt->execute([$email]);$user=$stmt->fetch();
    $valid=$allowed&&$human&&$user&&password_verify($password,$user['password_hash']);
    event_record('admin_login',$identifier,(bool)$valid,['email_hash'=>hash('sha256',$email)]);event_record('admin_login_ip',client_hash(),(bool)$valid);
