if(admin()&&$_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();
    $mfaAction=isset($_POST['mfa_prepare'])||isset($_POST['mfa_enable'])||isset($_POST['mfa_disable']);if(!$mfaAction&&!isset($_POST['logout']))require_admin_mfa();
    if(isset($_POST['mfa_prepare'])){
        $stmt=$db->prepare('SELECT password_hash FROM admin_users WHERE id=?');$stmt->execute([$_SESSION['admin_id']]);$current=is_string($_POST['current_password']??null)?$_POST['current_password']:'';$hash=(string)$stmt->fetchColumn();
        if(!password_verify($current,$hash))$error=t('admin.password_invalid');else{$_SESSION['mfa_setup_secret']=base32_encode_secret(random_bytes(20));$_SESSION['mfa_setup_at']=time();$notice=t('admin.mfa_prepare');}
