    if(isset($_POST['mfa_enable'])){
        $secret=safe_text($_SESSION['mfa_setup_secret']??'',64);$current=is_string($_POST['current_password']??null)?$_POST['current_password']:'';$code=safe_text($_POST['mfa_code']??'',20);$stmt=$db->prepare('SELECT * FROM admin_users WHERE id=?');$stmt->execute([$_SESSION['admin_id']]);$user=$stmt->fetch();$valid=$secret!==''&&($_SESSION['mfa_setup_at']??0)>=time()-600&&$user&&password_verify($current,(string)$user['password_hash'])&&totp_verify_step($secret,$code) !== false;
        if(!$valid)$error=t('admin.mfa_invalid');else{$db->beginTransaction();try{$db->prepare('UPDATE admin_users SET totp_secret=?,mfa_enabled=1,totp_last_step=NULL WHERE id=?')->execute([protect($secret),$_SESSION['admin_id']]);$db->prepare('DELETE FROM admin_recovery_codes WHERE admin_id=?')->execute([$_SESSION['admin_id']]);$codes=recovery_codes_new();$insert=$db->prepare('INSERT INTO admin_recovery_codes(admin_id,code_hash) VALUES(?,?)');foreach($codes as $recovery)$insert->execute([$_SESSION['admin_id'],password_hash(str_replace('-','',$recovery),password_algo())]);$db->commit();$_SESSION['admin_mfa']=true;unset($_SESSION['mfa_setup_secret'],$_SESSION['mfa_setup_at']);$_SESSION['new_recovery_codes']=$codes;audit('mfa_enabled','admin',(string)$_SESSION['admin_id']);$notice=t('admin.mfa_enabled');}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error=t('admin.mfa_invalid');}}
    }
    if(isset($_POST['mfa_disable'])){
        $current=is_string($_POST['current_password']??null)?$_POST['current_password']:'';$code=safe_text($_POST['mfa_code']??'',20);$stmt=$db->prepare('SELECT * FROM admin_users WHERE id=?');$stmt->execute([$_SESSION['admin_id']]);$user=$stmt->fetch();
        if(!$user||!password_verify($current,(string)$user['password_hash'])||!verify_admin_second_factor($user,$code))$error=t('admin.mfa_invalid');else{$db->prepare('UPDATE admin_users SET totp_secret=NULL,mfa_enabled=0,totp_last_step=NULL WHERE id=?')->execute([$_SESSION['admin_id']]);$_SESSION['admin_mfa']=false;audit('mfa_disabled','admin',(string)$_SESSION['admin_id']);$notice=t('admin.mfa_disabled');}
    }
    if(isset($_POST['save_product'])){
        $titles=[];$descriptions=[];foreach(SUPPORTED_LANGUAGES as $code){$titles[$code]=safe_text($_POST['title_'.$code]??'',140);$descriptions[$code]=safe_text($_POST['description_'.$code]??'',1200);}
        $category=safe_text($_POST['category']??'',60);$tech=safe_text($_POST['tech']??'',160);$price=filter_var($_POST['price']??null,FILTER_VALIDATE_FLOAT);
        if(!$titles['sq']||!$descriptions['sq']||!$category||!$tech||$price===false||$price<=0||$price>100000){$error=t('error.required');}
        else{
            $slug=strtolower(trim((string)preg_replace('/[^a-zA-Z0-9]+/','-',$titles['en']?:$titles['sq']),'-')).'-'.bin2hex(random_bytes(3));
            $db->beginTransaction();try{$stmt=$db->prepare('INSERT INTO products(title,slug,category,description,tech,price,featured) VALUES(?,?,?,?,?,?,?)');$stmt->execute([$titles['sq'],$slug,$category,$descriptions['sq'],$tech,$price,isset($_POST['featured'])?1:0]);$id=(int)$db->lastInsertId();$translation=$db->prepare('INSERT INTO product_translations(product_id,lang,title,description) VALUES(?,?,?,?)');foreach(SUPPORTED_LANGUAGES as $code)$translation->execute([$id,$code,$titles[$code]?:$titles['sq'],$descriptions[$code]?:$descriptions['sq']]);$db->commit();audit('product_created','product',(string)$id);redirect('admin.php?tab=products&saved=1');}catch(Throwable $e){$db->rollBack();throw $e;}
        }
    }
    if(isset($_POST['delete_product'])){$id=(int)($_POST['product_id']??0);$db->prepare('UPDATE products SET active=0 WHERE id=?')->execute([$id]);audit('product_archived','product',(string)$id);redirect('admin.php?tab=products&saved=1');}
    if(isset($_POST['upload_package'])){$id=(int)($_POST['product_id']??0);$version=safe_text($_POST['version']??'1.0.0',30);try{if(rate_limited('package_upload',client_hash(),10,3600))throw new RuntimeException('Upload rate limit.');$stmt=$db->prepare('SELECT id FROM products WHERE id=? AND active=1');$stmt->execute([$id]);if(!$stmt->fetch())throw new RuntimeException('Unknown product.');secure_product_upload($id,$_FILES['package']??[],$version);event_record('package_upload',client_hash(),true,['product_id'=>$id]);audit('package_uploaded','product',(string)$id);redirect('admin.php?tab=products&saved=1');}catch(Throwable $e){event_record('package_upload',client_hash(),false,['product_id'=>$id]);error_log('Package upload error: '.$e->getMessage());$error=t('error.package');}}
    if(isset($_POST['order_status'])){$allowed=['pending','paying','paid','payment_error','cancelled','refunded'];$transitions=['pending'=>['paying','paid','payment_error','cancelled'],'paying'=>['paid','payment_error','cancelled'],'payment_error'=>['paying','paid','cancelled'],'cancelled'=>['pending'],'paid'=>['refunded'],'refunded'=>[]];$status=is_string($_POST['status']??null)?$_POST['status']:'';$id=(int)($_POST['order_id']??0);$stmt=$db->prepare('SELECT status FROM orders WHERE id=?');$stmt->execute([$id]);$current=(string)$stmt->fetchColumn();if(in_array($status,$allowed,true)&&$current!==''&&($status===$current||in_array($status,$transitions[$current]??[],true))){$db->prepare('UPDATE orders SET status=?,updated_at=CURRENT_TIMESTAMP WHERE id=?')->execute([$status,$id]);if($status==='paid')fulfill_order($id);audit('order_status_changed','order',(string)$id);}redirect('admin.php?tab=orders&saved=1');}
    if(isset($_POST['save_payments'])){
        $stmt=$db->prepare('SELECT password_hash FROM admin_users WHERE id=?');$stmt->execute([$_SESSION['admin_id']]);$hash=(string)$stmt->fetchColumn();$current=is_string($_POST['current_password']??null)?$_POST['current_password']:'';
        $publicUrl=rtrim(safe_text($_POST['site_url']??'',250),'/');$urlValid=(bool)filter_var($publicUrl,FILTER_VALIDATE_URL);$scheme=parse_url($publicUrl,PHP_URL_SCHEME);$host=parse_url($publicUrl,PHP_URL_HOST);$local=in_array($host,['localhost','127.0.0.1','::1'],true);
        $paypalId=safe_text($_POST['paypal_client_id']??'',220);$paypalSecret=trim((string)($_POST['paypal_secret']??''));$paypalReady=!isset($_POST['paypal_enabled'])||($paypalId!==''&&($paypalSecret!==''||setting('paypal_secret','',true)!==''));
        $btcpayUrl=rtrim(safe_text($_POST['btcpay_url']??'',250),'/');$btcpayStore=safe_text($_POST['btcpay_store_id']??'',180);$btcpayKey=trim((string)($_POST['btcpay_api_key']??''));$btcpayHost=parse_url($btcpayUrl,PHP_URL_HOST);$btcpayLocal=in_array($btcpayHost,['localhost','127.0.0.1','::1'],true);$btcpayReady=!isset($_POST['btcpay_enabled'])||((bool)filter_var($btcpayUrl,FILTER_VALIDATE_URL)&&(parse_url($btcpayUrl,PHP_URL_SCHEME)==='https'||$btcpayLocal)&&$btcpayStore!==''&&($btcpayKey!==''||setting('btcpay_api_key','',true)!==''));
        if(!password_verify($current,$hash)||!$urlValid||($scheme!=='https'&&!$local))$error=t('admin.password_invalid');elseif(!$paypalReady||!$btcpayReady)$error=t('error.payment');
        else{
            save_setting('site_url',$publicUrl);save_setting('paypal_enabled',isset($_POST['paypal_enabled'])?'1':'0');save_setting('paypal_mode',($_POST['paypal_mode']??'sandbox')==='live'?'live':'sandbox');save_setting('paypal_client_id',$paypalId);
            if($paypalSecret!=='')save_setting('paypal_secret',$paypalSecret,true);
