            save_setting('manual_enabled',isset($_POST['manual_enabled'])?'1':'0');save_setting('manual_title',safe_text($_POST['manual_title']??'',100));save_setting('manual_instructions',safe_text($_POST['manual_instructions']??'',1500));audit('payment_settings_updated','settings','payments');redirect('admin.php?tab=payments&saved=1');
        }
